row(33, 4, 'MATERIAL', f'AND EGYPT WAS BURYING THOSE WHOM THE LORD HAD SMITTEN AMONG THEM, EVERY FIRSTBORN; AND ON THEIR GODS THE LORD EXECUTED JUDGMENTS — THE RUN OF EXODUS 12:12, RECORDED ONLY HERE. {HP(33, 4, (("ומצרים", "מקברים"), "and Egypt WAS BURYING — the participle\'s two Bible seats (Ezekiel 39:14\'s buriers of Gog the other) (computed)"), (("את", "אשר", "הכה", "יהוה", "בהם", "כל", "בכור"), "those whom the LORD had smitten among them, every firstborn — Exodus 12:29\'s run (\'the LORD smote every firstborn in the land of Egypt\') (computed)"), (("ובאלהיהם", "עשה", "יהוה", "שפטים"), "AND ON THEIR GODS THE LORD EXECUTED JUDGMENTS — one seat: THE RUN of Exodus 12:12\'s \'on all the gods of Egypt I will execute judgments\' (the future form at Exodus 12:12 and Ezekiel 25:11 alone; the perfect nowhere else) — Exodus narrates the firstborn smitten and never the judgments on the gods; the itinerary alone records that run, forty years on (computed); the store glosses \'sentence\'"))} → {AP(33, 4, (("ומצראי", "מקברין", "ית", "די", "קטל", "יי", "בהון"), "and the Egyptians were burying those whom the LORD had KILLED among them"), (("כל", "בוכרא"), "every firstborn"), (("ובטעותהון", "עבד", "יי", "דינין"), "and on THEIR IDOLS (their errors) the LORD executed judgments — the word for Peor\'s gods at 25:2 and here (computed)"))}.')
row(33, 5, 'MATERIAL', f'AND THE CHILDREN OF ISRAEL JOURNEYED FROM RAMESES AND CAMPED IN SUCCOTH — EXODUS 12:37\'S OPENING WORDS, THE ITINERARY\'S FIRST LINE. {HP(33, 5, (("ויסעו", "בני", "ישראל", "מרעמסס"), "and the children of Israel journeyed from Rameses — Exodus 12:37 opens with the same four words and adds \'to Succoth\' with the directional ending and the six hundred thousand; the departure from Rameses told TWICE (33:3 with its date, here as the itinerary\'s own first line) — the forty-two \'journeyed\' tokens count it twice (computed)"), (("ויחנו", "בסכת"), "and camped in Succoth — Exodus 12:37, 13:20 the earlier seats (computed)"))} → {AP(33, 5, (("ונטלו", "בני", "ישראל", "מרעמסס"), "and the children of Israel journeyed from Rameses"), (("ושרו", "בסכת"), "and camped in Succoth"))}.')
